    },
    rotation = {
        wowhead = {
            { text = "/ - These two talents offer near-identical damage boosts regardless of Hero Talent choice or target count. With that being said, Shado-Pan players will slightly favor due to its increase in generation. When aiming to maximize your damage, you can also select both talents.", spellId = 383695 },
            { text = "- If you are in a situation where you need to be in more direct control of your health, particularly if needing to react to consecutive spikes of damage, then it may make sense to not use this talent. It is otherwise a strong default choice, particularly when learning the specialization.", spellId = 1241097 },
            { text = "- While it will not help you survive massive hits of damage, this talent considerably reduces your healing burden over time.", spellId = 393357 },
            { text = "- This talent stands to become one of your biggest optional defensive gains under most circumstances when you feel in need of it.", spellId = 196737 },
            { text = "- While its damage potential is decent, this talent is unable to trigger if you are not always tanking or are fighting an enemy whose attacks cannot be dodged; consider it something nice to have in raid, but not needed if a point's demanded elsewhere.", spellId = 383785 },
            { text = "- The passive healing from the Fire and Nature damage in your kit results in a steady stream of mitigation that rapidly scales in value as the number of targets in an encounter increases. However, this will rarely be effective in saving your life; consider it a helpful tool on the level of .", spellId = 1262659 },
            { text = "- For add-heavy encounters, this talent offers an extra bit of burst threat to your , but is often difficult to pick up without compromising your defenses.", spellId = 1262017 },
            { text = "- While this talent does enable frequent usage of for added healing, it will rarely be an effective use of an ability over something more productive. Still, it has moments of strength when you are truly alone without a healer, and is something of a \"default\" choice when considering the spare points available in this section of the class tree.", spellId = 388812 },
            { text = "- Dungeons tend to feature a much larger number of effects to interrupt, giving you ample opportunity to accrue cooldown reduction on in particular. However, it can be hard to fit this point in over something more generally useful.", spellId = 450631 },
            { text = "- Use this in the odd dungeon where a boss or other enemy needs to quickly move out of an area, even at the cost of players potentially losing uptime.", spellId = 328670 },
            { text = "- While you usually have enough mobility on your own to kite with ease, a pre-placed for kiting becomes even more powerful with this talent's potent snare.", spellId = 450595 },
            { text = "- Although this talent claims to affect all of your healing done, it will only work on a very small number of Brewmaster abilities which includes / and . Still, it is a talent you are able to select whenever is not necessary.", spellId = 389579 },
            { text = "- By being able to remove snare effects with on occasion, you may have the opportunity to then cast on an ally and remove a similar effect from them at the same time. Just remember that this talent will not remove root effects!", spellId = 450622 },
            { text = "- Having access to an extra dispel in a group where usually only the healer can remove Magic debuffs is an excellent prospect, but being tied to your strongest defensive cooldown of greatly limits this talent's potential; the redirection effect is also usually irrelevant.", spellId = 1243287 },
            { text = "- With only one healer present, Mythic+ dungeons tend to ask for a bit more self-reliance from tanks; this talent gives you an extra cushion in dangerous moments to help with that task, but its lack of noteworthy pathing to other talents makes it difficult to recommend if you don't truly need its defense; you may even have to sacrifice / to select it.", spellId = 455139 },
            { text = "- In higher key levels where dodging boss autoattacks can be useful, this talent gains (limited) use. Otherwise, you are likely exceeding 100% dodge on a regular basis when fighting groups of enemies, negating much of its value.", spellId = 454484 },
            { text = "- If your key level features regular Tankbuster hits for large portions of your health, this talent is fantastic for boosting your during those dangerous moments. That said, it's also important to consider the limited value of this talent versus another defensive alternative.", spellId = 455068 },
            { text = ". Notably, 14.3% Haste results in a 7-second cooldown, and 33.4% a 6-second cooldown.", spellId = 121253 },
            { text = "/ (from faster auto attacks)", spellId = 418359 },
            { text = "Brewmaster Monks start with 7.4% Dodge chance per stack and an Attack Power increase of 8%.", spellId = nil },
            { text = "You may reach 100% dodge chance or more, especially through ; any extra dodge chance is \"wasted\" when reset.", spellId = 100784 },
            { text = "Many enemy abilities cannot be dodged, though dodgeable attacks often make up the majority of your damage taken.", spellId = nil },
